def escapeImp : String → optParam Bool true → String :=
fun s quote =>
  (have cs := s.data;
    have cs := replaceChar cs '&' ampEnt;
    have cs := replaceChar cs '<' ltEnt;
    have cs := replaceChar cs '>' gtEnt;
    have __do_jp := fun cs y => pure { data := cs };
    if quote = true then
      have cs := replaceChar cs '\"' quotEnt;
      have cs := replaceChar cs '\'' aposEnt;
      do
      let y ← pure PUnit.unit
      __do_jp cs y
    else do
      let y ← pure PUnit.unit
      __do_jp cs y).run
